    private static readonly PropertyDescriptor<Probe, double> X = new("X", n => n.X, (n, v) => { n.X = v; n.Hook?.Invoke(); });
    internal static void Run() { Authoring(); Fades(); Routes(); Timing(); Boundaries(); Groups(); SharingAndFailure(); Effects(); TestingAndWarm(); Console.WriteLine("Animation state-machine checks passed."); }
    private static void Authoring()
    {
        using var machine = new AnimationNodeStateMachine(); using var leaf = new AnimationNodeAnimation(); using var edge = new AnimationNodeStateMachineTransition();
        Check(machine.GetNodeList().SequenceEqual(new[] { "End", "Start" }) && machine.StateMachineType == AnimationStateMachineType.Root && !machine.ResetEnds && !machine.AllowTransitionToSelf, "Machine defaults.");
        Check(edge.AdvanceMode == AnimationAdvanceMode.Enabled && edge.SwitchMode == AnimationSwitchMode.Immediate && edge.Reset && edge.Priority == 1 && edge.XFadeTime == 0, "Edge defaults.");
        Reject<ArgumentException>(() => machine.AddNode("bad/name", leaf)); Reject<ArgumentException>(() => machine.AddNode("loop", machine)); using var ordinary = new AnimationNode(); Reject<ArgumentException>(() => machine.AddNode("ordinary", ordinary));
        machine.AddNode("a", leaf, new(1, 2)); machine.AddNode("b", leaf); machine.SetGraphOffset(new(3, 4)); machine.AddTransition("Start", "a", edge); machine.AddTransition("a", "b", edge);
        Reject<ArgumentException>(() => machine.AddTransition("a", "a", edge)); Reject<ArgumentException>(() => machine.AddTransition("a", "b", edge)); Reject<ArgumentException>(() => machine.RemoveNode("Start")); Reject<ArgumentException>(() => machine.ReplaceNode("End", leaf));
        Reject<ArgumentOutOfRangeException>(() => edge.XFadeTime = -1); Reject<ArgumentOutOfRangeException>(() => edge.XFadeTime = double.NaN); Reject<ArgumentOutOfRangeException>(() => edge.Priority = -1); Reject<ArgumentOutOfRangeException>(() => edge.SwitchMode = (AnimationSwitchMode)99);
        var notices = 0; edge.AdvanceConditionChanged += () => notices++; var key = new AnimationParameter<bool>("ready", false); edge.AdvanceCondition = key; edge.AdvanceCondition = key; Check(notices == 2, "Equal condition assignments notify.");
        machine.RenameNode("a", "renamed"); Check(machine.GetTransitionTo(0) == "renamed" && machine.GetTransitionFrom(1) == "renamed" && machine.GetNodePosition("renamed") == new Vector2(1, 2), "Rename updates edges and metadata.");
        using var copy = (AnimationNodeStateMachine)machine.Duplicate(); using var deep = (AnimationNodeStateMachine)machine.Duplicate(true); Check(ReferenceEquals(copy.GetNode("b"), leaf) && ReferenceEquals(copy.GetTransition(0), edge), "Shallow borrowing."); Check(!ReferenceEquals(deep.GetNode("b"), leaf) && ReferenceEquals(deep.GetNode("b"), deep.GetNode("renamed")) && ReferenceEquals(deep.GetTransition(0), deep.GetTransition(1)), "Deep aliases.");
        var deepLeaf = deep.GetNode("b"); var deepEdge = deep.GetTransition(0); machine.RemoveNode("renamed"); Check(machine.GetTransitionCount() == 0 && !leaf.IsDisposed && !edge.IsDisposed && copy.HasTransition("renamed", "b"), "Independent topology and borrowed lifetime."); deepLeaf.Dispose(); deepEdge.Dispose();
    }
    private static void Fades()
