        using var setup = new Setup(); using var edge = new AnimationNodeStateMachineTransition { XFadeTime = 1 }; setup.Machine.AddTransition("a", "b", edge); var events = new List<string>(); setup.Playback.StateStarted += s => events.Add("+" + s); setup.Playback.StateFinished += s => events.Add("-" + s);
