        setup.Tree.Advance(.5); Near(setup.Target.X, 20); Near(setup.Playback.GetFadingPosition(), .5); Near(setup.Playback.GetFadingLength(), 1); Near(setup.Playback.GetCurrentLength(), 4); Near(setup.Playback.GetFadingFromLength(), 4);
        setup.Tree.Advance(.5); Near(setup.Target.X, 30); Check(setup.Playback.GetFadingFromNode() == "" && events.IndexOf("+b") < events.IndexOf("-a"), "Outgoing finish follows destination start.");
        setup.Playback.Start("a"); setup.Tree.Advance(0); Near(setup.Target.X, 10); using var curve = new Curve(); curve.AddPoint(new(0, 0)); curve.AddPoint(new(.5f, .25f)); curve.AddPoint(new(1, 1)); edge.XFadeCurve = curve; setup.Playback.Travel("b"); setup.Tree.Advance(0); setup.Tree.Advance(.5); Near(setup.Target.X, 15);
        setup.Playback.Next(); setup.Tree.Advance(0); Check(setup.Playback.GetFadingFromNode() == "a", "Next without any selected successor preserves fade."); setup.Playback.Stop(); setup.Tree.Advance(0); Check(!setup.Playback.IsPlaying() && setup.Playback.GetTravelPath().Length == 0 && setup.Playback.GetFadingFromNode() == "", "Stop cleanup.");
        setup.Playback.Start("a", false); setup.Tree.Advance(0); Check(setup.Playback.IsPlaying() && setup.Playback.ResourceLocalToScene, "Restart and local controller.");
        edge.XFadeCurve = null; edge.XFadeTime = 0; setup.Playback.Travel("b"); setup.Tree.Advance(0); setup.Tree.Advance(0); Near(setup.Target.X, 30);
        setup.Machine.AddTransition("b", "End", edge); setup.Playback.Travel("End"); setup.Tree.Advance(0); Check(setup.Playback.GetCurrentNode() == "End" && setup.Playback.IsPlaying(), "End exits while retaining active control.");
    }
    private static void Routes()
