        using var direct = new AnimationNodeStateMachineTransition { Priority = 10, SwitchMode = AnimationSwitchMode.AtEnd }; using var via = new AnimationNodeStateMachineTransition { SwitchMode = AnimationSwitchMode.AtEnd }; setup.Machine.AddTransition("a", "c", direct); setup.Machine.AddTransition("a", "b", via); setup.Machine.AddTransition("b", "c", via); setup.Tree.Advance(0);
        setup.Playback.Travel("c"); setup.Tree.Advance(0); Check(setup.Playback.GetTravelPath().SequenceEqual(new[] { "b", "c" }), "Geometric priority route."); var snapshot = setup.Playback.GetTravelPath(); snapshot[0] = "bad"; Check(setup.Playback.GetTravelPath()[0] == "b", "Route snapshot ownership.");
