        setup.Tree.Advance(.5); var prior = setup.Playback.GetCurrentPlayPosition(); setup.Playback.Travel("c"); setup.Tree.Advance(0); Near(setup.Playback.GetCurrentPlayPosition(), prior); setup.Machine.AllowTransitionToSelf = true; setup.Playback.Travel("c"); setup.Tree.Advance(0); Near(setup.Playback.GetCurrentPlayPosition(), 0);
