        var flag = new AnimationParameter<bool>("ready", false); edge.AdvanceMode = AnimationAdvanceMode.Auto; edge.AdvanceCondition = flag; edge.AdvanceExpression = t => t.GetParameter("", flag); setup.Playback.Start("a"); setup.Tree.Advance(0); Check(setup.Playback.GetCurrentNode() == "a", "False flag suppresses automatic edge."); setup.Tree.SetParameter("", flag, true); setup.Tree.Advance(0); Check(setup.Playback.GetCurrentNode() == "b", "Typed condition and predicate execute.");
        edge.AdvanceCondition = null; edge.AdvanceExpression = null; edge.SwitchMode = AnimationSwitchMode.AtEnd; setup.Clips[0].LoopMode = SpriteFrames.LoopMode.Linear; setup.Playback.Start("a"); setup.Tree.Advance(0); setup.Tree.Advance(3.9); Check(setup.Playback.GetCurrentNode() == "a", "Loops wait without BreakLoopAtEnd."); edge.BreakLoopAtEnd = true; setup.Tree.Advance(.05); Check(setup.Playback.GetCurrentNode() == "b", "Loop break uses predicted cycle endpoint.");
        using var back = new AnimationNodeStateMachineTransition { AdvanceMode = AnimationAdvanceMode.Auto }; edge.SwitchMode = AnimationSwitchMode.Immediate; setup.Machine.AddTransition("b", "a", back); setup.Playback.Start("a"); setup.Tree.Advance(0); Check(setup.Playback.IsPlaying(), "Zero-duration automatic cycles terminate within a pass.");
    }
